data = FileAttachment("../../../data/sources.csv").csv({typed: true})
country = data.filter(d =&gt; d.country === "Greece")
















viewof topicSel = Inputs.select(["All", ...Array.from(new Set(country.map(d =&gt; d.topic)))], {label: "Topic", value: "All"})
viewof channelSel = Inputs.select(["All","Website","Social media"], {label: "Channel", value: "All"})
viewof dsOnly = Inputs.toggle({label: "Datasets only", value: false})
viewof q = Inputs.text({label: "Search", placeholder: "name, type, note…", width: 260})
viewof sortBy = Inputs.select(new Map([
  ["Composite ↓","composite"], ["Accuracy ↓","accuracy"], ["Uniqueness ↓","uniqueness"],
  ["Timeliness ↓","timeliness"], ["Transparency ↓","transparency"], ["Verifiability ↓","verifiability"],
  ["Accessibility ↓","accessibility"], ["Depth ↓","depth"], ["Name A–Z","name"]
]), {label: "Sort by", value: "composite"})





































filtered = {
  let rows = country;
  if (topicSel !== "All") rows = rows.filter(d =&gt; d.topic === topicSel);
  if (channelSel !== "All") rows = rows.filter(d =&gt; d.channel === channelSel);
  if (dsOnly) rows = rows.filter(d =&gt; d.is_dataset === "yes");
  if (q) { const s = q.toLowerCase();
    rows = rows.filter(d =&gt; (d.name+" "+d.source_type+" "+d.notes+" "+d.perspective+" "+d.platform).toLowerCase().includes(s)); }
  return rows.slice().sort((a,b) =&gt; sortBy === "name"
    ? (a.name &lt; b.name ? -1 : a.name &gt; b.name ? 1 : 0) : (b[sortBy]-a[sortBy]));
}







html`&lt;p class="count"&gt;&lt;strong&gt;${country.length}&lt;/strong&gt; sources · &lt;strong&gt;${country.filter(d=&gt;d.is_dataset==="yes").length}&lt;/strong&gt; datasets · showing &lt;strong&gt;${filtered.length}&lt;/strong&gt; — by topic: ${["Security","Economic","Political","Societal","General"].map(t =&gt; `${t} ${country.filter(d=&gt;d.topic===t).length}`).join(" · ")}&lt;/p&gt;`







function scoreBadge(v){ return html`&lt;span class="score score-${Math.round(v)}"&gt;${v}&lt;/span&gt;`; }
function compBadge(v){ return html`&lt;span class="score composite score-${Math.round(v)}"&gt;${v}&lt;/span&gt;`; }
function pillClass(p){ return p.startsWith("Independent") ? "pill-indep" : p.startsWith("Pro-") ? "pill-prowar" : "pill-state"; }
function srcCell(d){ return html`&lt;td&gt;&lt;a href="${d.url}" target="_blank" rel="noopener" class="src-name"&gt;${d.name}&lt;/a&gt;
  &lt;span class="pill ${pillClass(d.perspective)}"&gt;${d.perspective}&lt;/span&gt;${d.channel==="Social media" ? html`&lt;span class="pill pill-social"&gt;${d.platform}&lt;/span&gt;` : ""}${d.is_dataset==="yes" ? html`&lt;span class="pill pill-dataset"&gt;dataset&lt;/span&gt;` : ""}
  &lt;span class="src-note"&gt;${d.notes}&lt;/span&gt;&lt;/td&gt;`; }
function scoreCells(d){ return html`${[d.accuracy,d.uniqueness,d.timeliness,d.transparency,d.verifiability,d.accessibility,d.depth].map(v=&gt;html`&lt;td class="num"&gt;${scoreBadge(v)}&lt;/td&gt;`)}&lt;td class="num"&gt;${compBadge(d.composite)}&lt;/td&gt;`; }





































html`&lt;div class="osal-scroll"&gt;&lt;table class="osal"&gt;
  &lt;thead&gt;&lt;tr&gt;&lt;th&gt;Source&lt;/th&gt;&lt;th&gt;Topic&lt;/th&gt;
    &lt;th class="num" title="Accuracy | Uniqueness | Timeliness | Transparency & bias disclosure | Verifiability | Accessibility | Analytical depth | Composite"&gt;Acc | Uni | Tim | Tra | Ver | Acs | Dep | Comp&lt;/th&gt;
    &lt;/tr&gt;&lt;/thead&gt;
  &lt;tbody&gt;${filtered.map(d =&gt; html`&lt;tr&gt;${srcCell(d)}&lt;td&gt;${d.topic}&lt;/td&gt;${scoreCells(d)}&lt;/tr&gt;`)}&lt;/tbody&gt;
&lt;/table&gt;&lt;/div&gt;`












